window.DEFAULT_SCHEMAS = {"RegionResponseV6.schema.json":{"$schema":"https://json-schema.org/draft/2020-12/schema","$id":"https://scrappirates.example/schemas/region-response-v5.schema.json","title":"Scrap Pirates Region Response V5","description":"Defines durable regional world content for AI generation. Omit collections and optional fields when there is nothing meaningful to say; mission-specific characters, cargo, and transient story state belong in mission responses.","type":"object","additionalProperties":false,"properties":{"factions":{"type":"array","description":"Factions introduced by this region. Omit when the region introduces none.","items":{"$ref":"#/$defs/Faction"}},"systems":{"type":"array","description":"Star systems defined by this response.","items":{"$ref":"#/$defs/System"},"minItems":1},"locations":{"type":"array","description":"Dockable stations or landable ports. All inhabited systems should have at least one.","items":{"$ref":"#/$defs/Location"}},"equipmentDefinitions":{"type":"array","description":"Custom equipment definitions introduced by this region. Omit when there are none.","items":{"$ref":"#/$defs/EquipmentDefinition"}},"shipCards":{"type":"array","description":"Custom ship type definitions introduced by this region. Omit when there are none.","items":{"$ref":"#/$defs/ShipCard"}},"decks":{"type":"array","description":"Weighted content decks introduced by this region. Omit when there are none.","items":{"$ref":"#/$defs/Deck"}}},"required":["systems"],"$defs":{"FactionRelation":{"type":"object","description":"Non-neutral starting relationship from one faction to another. Omit neutral relationships.","properties":{"factionRef":{"description":"Name of the faction or allegiance this relationship points to.","type":"string","minLength":1},"stance":{"description":"Starting stance toward the referenced faction.","type":"string","enum":["Friendly","Hostile","Neutral"]}},"additionalProperties":false,"required":["factionRef","stance"]},"Faction":{"type":"object","description":"A durable faction the DM can use for ownership, conflict, encounters, and world reactions.","properties":{"name":{"description":"Player-facing faction name; also used by factionRef fields.","type":"string","minLength":1},"affinity":{"description":"Gameplay affinity/color. Blue often fits corporate factions, Yellow often fits sparrows, and Green often fits authoritarians or brigands. Red is for rare advanced, secretive, or alien factions.","type":"string","enum":["Green","Blue","Yellow","Red"]},"description":{"description":"What the faction wants, how it behaves, and what makes interacting with it distinctive.","type":"string","minLength":1},"shipDecks":{"type":"array","items":{"$ref":"#/$defs/Deck"},"description":"Custom ship deck IDs, up to one per color. Omitted classes use the default/fallback deck. This can be left blank for most small factions, as they lack the resources to make custom ships. "},"moduleDecks":{"type":"array","description":"Custom ship deck IDs, up to one per color. Omitted classes use the default/fallback deck. This can be left blank for most small factions, as they lack the resources to make custom ships. ","items":{"$ref":"#/$defs/Deck"}},"relations":{"type":"array","description":"Explicit non-neutral relationships to other factions. Unlisted factions are Neutral. The values in the allegiance enum are also valid relations targets. ","items":{"$ref":"#/$defs/FactionRelation"}},"secretInfo":{"type":"string","description":"Hidden motives, internal politics, leverage, or truths available to the AI DM but not revealed by default.","minLength":1},"id":{"type":"string","minLength":1},"hostileToPlayer":{"type":"boolean","description":"Initial hostility toward the captain. Default false."},"friendlyToPlayer":{"type":"boolean","description":"Initially friendly to the captain; automatic support when joining a fight against a non-friendly side. Hostility overrides friendship. Default false."},"stature":{"description":"Narrative scale or role of the faction.","type":"string","minLength":1,"enum":["company","local","regional","galactic"]},"allegiance":{"type":"string","description":"Galaxy-wide groups that the faction fits into for determining hostility. If another faction is hostie to this faction's allegiance, it is also hostile to this faction. A faction can be hostile to its own allegiance - for example, a particular brigand outfit might be hostile to other brigands.","enum":["None","Syndicate","Sparrows","Warlords","Brigands","Aliens"]}},"additionalProperties":false,"required":["name","affinity","description","id"]},"System":{"type":"object","description":"Canonical facts for one generated star system.","properties":{"address":{"type":"string","pattern":"^[1-7]{1,13}$","description":"Coordinate identity: 1–13 digits, each 1–7. The galaxy uses a tree structure, where parent systems remove a digit and child systems add a digit, and parents and children can be traversed."},"tech":{"type":"integer","minimum":0},"controllerRef":{"description":"Stable faction ID of the primary governing faction. If blank, falls back to the Syndicate.","type":"string","minLength":1},"minorRef":{"description":"Stable faction ID of a secondary faction that visits this system. If the system is a conflict zone, this is the other faction in the conflict. Falls back to Brigands.","type":"string","minLength":1},"description":{"description":"Concise canonical identity of the system: what would the local traders know about it?","type":"string","minLength":1},"name":{"description":"Player-facing system name.","type":"string","minLength":1},"civilianRef":{"description":"Civilian faction associated with the system, or null when none is defined.","type":["string","null"]}},"additionalProperties":false,"required":["address","description"]},"Location":{"type":"object","description":"A dockable station or landable planetary port inside a system.","properties":{"name":{"description":"Player-facing location name.","type":"string","minLength":1},"systemRef":{"type":"string","pattern":"^[1-7]{1,13}$","description":"Coordinate identity: 1–13 digits, each 1–7."},"kind":{"description":"Location type.","type":"string","enum":["Station","PlanetPort"]},"description":{"description":"What this place is, what happens here, and why a player might care about it.","type":"string","minLength":1},"services":{"type":"array","description":"Recognized services the player can access here. Omit when none are available. Common: Repair, Job Board, Trade. Uncommon: Outfitter. Rare: Shipyard, Junkyard.","items":{"type":"string","enum":["Outfitter","Shipyard","Junkyard","Repair","Job Board","Trade"]},"uniqueItems":true},"appearance":{"description":"Short visual brief for depicting the location.","type":"string","minLength":1},"secretInfo":{"type":"string","minLength":1,"description":"Information about this location that's initially hidden from the player, but used by the DM. Internal politics, underworld dealings, secret bases - that kind of thing. "},"id":{"type":"string","minLength":1},"techLevel":{"type":"integer","minimum":0,"description":"How technologically advanced is this location? Affects ship spawning in orbit, and sold goods quality. 0 is uninhabited or technologically regressed. 1-4 is a spacer-town, 5-10 is more of a bustling city. A major center of a regional power might be 11-20, while core worlds are 20+"},"hidden":{"type":"boolean","default":false,"description":"Initially omitted from player navigation until RevealLocation in a mission."}},"additionalProperties":false,"required":["name","systemRef","kind","description","id"]},"WeaponProfile":{"type":"object","description":"Weapon-specific dice and shot information.","properties":{"shots":{"description":"Shots produced by one activation. Usually 1-4; higher damage generally means fewer shots. Yellow cannons tend to use more shots and smaller dieSides.","type":"integer","minimum":1},"baseDiceCount":{"description":"Attack dice rolled per shot. Usually 1; very powerful cannons may use 2-3.","type":"integer","minimum":1},"dieSides":{"description":"Faces on each base attack die. Typical dice are d4, d6, d8, d10, d12, or d20. Balance die size against shots, dice count, and effects.","type":"integer","enum":[4,6,8,10,12,20]}},"additionalProperties":false,"required":["shots","baseDiceCount","dieSides"]},"EquipmentEffect":{"$ref":"EquipmentEffects.schema.json#/$defs/EquipmentEffect"},"EquipmentDefinition":{"type":"object","description":"Immutable equipment definition available to ships or markets.","properties":{"id":{"description":"Stable ID used by deck entries and other references.","type":"string","minLength":1},"name":{"description":"Player-facing equipment name.","type":"string","minLength":1},"affinity":{"description":"Gameplay affinity/color.","type":"string","enum":["Green","Blue","Yellow","Red"]},"category":{"description":"Determines where the equipment might show up, and the price. For example, economy modules are used for merchants, not warships. ","type":"string","enum":["Armament","Defense","Economy"]},"defense":{"description":"Defense used by combat targeting/resolution. Delicate civilian equipment is often 1-3, cannons 3-5, and armor 5-7. Red modules might be 6-13 depending on their category.","type":"integer","minimum":0},"inputs":{"type":"array","minItems":3,"maxItems":3,"items":{"type":"string","enum":["","Green","Blue","Yellow","Red"]},"description":"Exactly three slots that must be connected by the player, top/middle/bottom. Colors must be distinct. With two inputs use [color, \"\", otherColor]. At least one input is required or the client will discard this equipment.  More powerful equipment can be balanced by needing more slots."},"weapon":{"description":"Weapon profile when this equipment is a weapon. Omit for non-weapons.","$ref":"#/$defs/WeaponProfile"},"effects":{"type":"array","description":"Registered engine effects applied by this equipment. Omit when it has no special effects. Most non-red equipment has zero or one effect type, but some effect types are designed to be specified in multiple EquipmentEffect objects.","items":{"$ref":"#/$defs/EquipmentEffect"}},"basePrice":{"description":"Base market price before local modifiers.","type":"integer","minimum":0},"description":{"type":"string","minLength":1,"description":"Player facing description that explains the item."},"portraitBrief":{"type":"string","minLength":1,"description":"Visual description of the item."}},"additionalProperties":false,"required":["id","name","affinity","category","defense","inputs","basePrice"]},"ShipCard":{"type":"object","description":"There are default ship cards as fallbacks for civilian use, but some factions are powerful or wealthy enough to have custom ship cards.","properties":{"id":{"description":"Stable ID used by ship decks.","type":"string","minLength":1},"name":{"description":"Player-facing NPC ship-card name.","type":"string","minLength":1},"affinity":{"description":"Gameplay affinity/color.","type":"string","enum":["Green","Blue","Yellow","Red"]},"class":{"description":"Ship class, typically small, medium, large, or capital.","type":"string","enum":["Small","Medium","Large","Capital"]},"portraitBrief":{"description":"Visual brief for the ship portrait.","type":"string","minLength":1},"coreDefense":{"description":"Base defense of the ship core. Generally 2-4 for small or civilian ships, 3-5 for medium ships, and 6-10 for large ships.","type":"integer","minimum":0},"warship":{"description":"If true, this ship will not use economy modules - only cannons and defense modules. ","type":"boolean"},"lootFuel":{"description":"A list of fuel tokens recoverable from a destroyed instance of this ship. Duplicate fuel tokens are expected - a ship might drop 4-12 depending on size and cargo capacity, and weighted towards the affinity color.","type":"array","items":{"type":"string","enum":["green","blue","yellow","red"]}},"lootHull":{"description":"A list of hull cards recoverable from a destroyed instance of this ship. Duplicate entries are expected.  A ship might drop 1-5 depending on size, and weighted towards the affinity color.","type":"array","items":{"type":"string","enum":["green","blue","yellow","red"]}},"shipSystems":{"description":"A list of functional ship system slots. Ship instances will draw from the faction's moduleDecks of the appropriate color for each slot, or the fallback civilian modules. Duplicate entries are expected. A ship would have roughly 2/4/6/10 for small/medium/large/capital class, with (rare) red systems being twice as strong as the others.","type":"array","items":{"type":"string","enum":["green","blue","yellow","red"]}}},"additionalProperties":false,"required":["id","name","affinity","class","portraitBrief","coreDefense","shipSystems","lootHull","lootFuel"]},"DeckEntry":{"type":"object","description":"Weighted entry in a generated content deck.","properties":{"definitionRef":{"description":"ID of the equipment definition or ship card drawn by this entry. Add a blank one to allow default/civilian ships in the deck, and use deck IDs to incorporate other decks.","type":"string","minLength":1},"weight":{"description":"Relative positive draw weight (number of copies in the deck.)","type":"integer","minimum":1}},"additionalProperties":false,"required":["definitionRef","weight"]},"Deck":{"type":"object","description":"Weighted content deck referenced by factions or encounters.","properties":{"id":{"description":"Stable deck ID used by faction deck bindings.","type":"string","minLength":1},"kind":{"description":"Definition category drawn by this deck - Ship or Module. Don't mix both Ships and Modules in one deck. ","type":"string","enum":["Ship","Module"]},"affinity":{"description":"Gameplay affinity/color.","type":"string","enum":["Green","Blue","Yellow","Red"]},"class":{"description":"Ship class restriction for a class-specific deck. Omit when not class-specific.","type":"string","enum":["Small","Medium","Large","Capital","Unspecific"]},"entries":{"type":"array","description":"The actual contents of this deck.","items":{"$ref":"#/$defs/DeckEntry"},"minItems":1}},"additionalProperties":false,"required":["id","kind","affinity","entries"]}}},"EquipmentEffectsV2.schema.json":{"$schema":"https://json-schema.org/draft/2020-12/schema","title":"Equipment effects","description":"Ordered equipment effects. Each object contains only kind and, where applicable, an optional integer value. Timing and other mechanics are engine presets.","type":"array","items":{"$ref":"#/$defs/EquipmentEffect"},"$defs":{"EquipmentEffect":{"oneOf":[{"type":"object","description":"This module must be targeted first. Good for defensive systems like armor.","properties":{"kind":{"const":"TargetPriority"}},"required":["kind"],"additionalProperties":false},{"type":"object","description":"Increases crit odds by adding an additional critical die face shipwide. Repeat for multiple faces.","properties":{"kind":{"const":"CriticalFaces"},"value":{"type":"integer","minimum":1,"maximum":20,"default":1}},"required":["kind"],"additionalProperties":false},{"type":"object","description":"Criticals happen at max dice face. This module adds additional criticals relative to the maximum.","properties":{"kind":{"const":"CriticalMaxOffset"},"value":{"type":"integer","minimum":-20,"maximum":-1,"default":-1}},"required":["kind"],"additionalProperties":false},{"type":"object","description":"Targeting modifier: choose the lowest-defense enemy system, once per round.","properties":{"kind":{"const":"TargetLowestDefense"}},"required":["kind"],"additionalProperties":false},{"type":"object","description":"One substitution die at round start; value is its number of sides. Repeat for more dice.","properties":{"kind":{"const":"GrantSubstitution"},"value":{"type":"integer","minimum":4,"maximum":20,"default":6}},"required":["kind"],"additionalProperties":false},{"type":"object","description":"One substitution using the current attack die size, after seeing a roll, once per round.","properties":{"kind":{"const":"SubstituteAfterRoll"}},"required":["kind"],"additionalProperties":false},{"type":"object","description":"One substitution on this weapon's failed hit, once per round.","properties":{"kind":{"const":"SubstituteFailedHit"}},"required":["kind"],"additionalProperties":false},{"type":"object","description":"One substitution on this weapon's undodged failed hit, once per shot.","properties":{"kind":{"const":"SubstituteUndodgedFailedHit"}},"required":["kind"],"additionalProperties":false},{"type":"object","description":"Shield amount, latched at round start while powered. Shields protect all modules.","properties":{"kind":{"const":"Shield"},"value":{"type":"integer","minimum":1,"maximum":20,"default":2}},"required":["kind"],"additionalProperties":false},{"type":"object","description":"Shield amount, latched at round start while connected; no power spend required.","properties":{"kind":{"const":"ConnectedShield"},"value":{"type":"integer","minimum":1,"maximum":20,"default":2}},"required":["kind"],"additionalProperties":false},{"type":"object","description":"Disable one own system when the final shot total equals value. Repeat for multiple totals. Good for high-risk, high-reward weapons.","properties":{"kind":{"const":"SelfDamage"},"value":{"type":"integer","minimum":1,"maximum":100,"default":6}},"required":["kind"],"additionalProperties":false},{"type":"object","description":"This weapon ignores shields. Use sparingly.","properties":{"kind":{"const":"IgnoreShields"}},"required":["kind"],"additionalProperties":false},{"type":"object","description":"Dodge charges granted at round start while powered. Good for thruster systems.","properties":{"kind":{"const":"Dodge"},"value":{"type":"integer","minimum":1,"maximum":100,"default":2}},"required":["kind"],"additionalProperties":false},{"type":"object","description":"Generate value Green fuel tokens on a successful round-start roll (d6 on 4-6), independent of equipment affinity. Generally 1.","properties":{"kind":{"const":"GenerateGreenFuel"},"value":{"type":"integer","minimum":1,"maximum":5,"default":1}},"required":["kind"],"additionalProperties":false},{"type":"object","description":"Generate value Blue fuel tokens on a successful round-start roll (d8 on 5-8), independent of equipment affinity. Generally 1.","properties":{"kind":{"const":"GenerateBlueFuel"},"value":{"type":"integer","minimum":1,"maximum":5,"default":1}},"required":["kind"],"additionalProperties":false},{"type":"object","description":"Generate value Yellow fuel tokens on a successful round-start roll (d4 on 2), independent of equipment affinity. Generally 1.","properties":{"kind":{"const":"GenerateYellowFuel"},"value":{"type":"integer","minimum":1,"maximum":5,"default":1}},"required":["kind"],"additionalProperties":false},{"type":"object","description":"Generate value Red fuel tokens on a successful round-start roll (d6 on 4-6), independent of equipment affinity. Generally 1.","properties":{"kind":{"const":"GenerateRedFuel"},"value":{"type":"integer","minimum":1,"maximum":5,"default":1}},"required":["kind"],"additionalProperties":false},{"type":"object","description":"Once per round, convert one selected fuel token into one Red token.","properties":{"kind":{"const":"ConvertFuel"}},"required":["kind"],"additionalProperties":false},{"type":"object","description":"Power tokens gained on activation; accumulated tokens attack all enemy systems. DM: DO NOT USE.","properties":{"kind":{"const":"StackingAreaDamage"},"value":{"type":"integer","minimum":1,"maximum":3,"default":1}},"required":["kind"],"additionalProperties":false},{"type":"object","description":"Each enemy system rolls d6 on activation; rolls below value suppress it for this round. DM: DO NOT USE.","properties":{"kind":{"const":"ActivationCheck"},"value":{"type":"integer","minimum":1,"maximum":6,"default":4}},"required":["kind"],"additionalProperties":false},{"type":"object","description":"Enemy turns skipped after critical damage. DM: DO NOT USE.","properties":{"kind":{"const":"SkipTurn"},"value":{"type":"integer","minimum":1,"maximum":2147483647,"default":1}},"required":["kind"],"additionalProperties":false},{"type":"object","description":"Excess shot total continues through the next automatic target.","properties":{"kind":{"const":"Penetration"}},"required":["kind"],"additionalProperties":false},{"type":"object","description":"This weapon ignores dodge abilities. Use sparingly. ","properties":{"kind":{"const":"IgnoreDodge"}},"required":["kind"],"additionalProperties":false},{"type":"object","description":"Enemy dodge charges removed on activation.","properties":{"kind":{"const":"RemoveDodge"},"value":{"type":"integer","minimum":1,"maximum":100,"default":1}},"required":["kind"],"additionalProperties":false},{"type":"object","description":"Maximum adjacent systems hit with half shot damage, ignoring shields, after a system is destroyed.","properties":{"kind":{"const":"Splash"},"value":{"type":"integer","minimum":1,"maximum":100,"default":2}},"required":["kind"],"additionalProperties":false},{"type":"object","description":"Own damaged systems repaired on activation.","properties":{"kind":{"const":"Repair"},"value":{"type":"integer","minimum":1,"maximum":5,"default":1}},"required":["kind"],"additionalProperties":false},{"type":"object","description":"Allow tunnelling (travel between numerically similar star systems) while connected and functional.","properties":{"kind":{"const":"EnableTunnelling"}},"required":["kind"],"additionalProperties":false},{"type":"object","description":"Additional cargo units while connected and functional. Reasonable range: 5-50","properties":{"kind":{"const":"CargoCapacity"},"value":{"type":"integer","minimum":1,"maximum":100,"default":5}},"required":["kind"],"additionalProperties":false},{"type":"object","description":"Additional passenger berths while connected and functional. Reasonable range: 1-10","properties":{"kind":{"const":"PassengerBerths"},"value":{"type":"integer","minimum":1,"maximum":100,"default":4}},"required":["kind"],"additionalProperties":false},{"type":"object","description":"Additional concealed cargo units while connected and functional - for smuggling. Reasonable range: 1-10. ","properties":{"kind":{"const":"ConcealedCargo"},"value":{"type":"integer","minimum":1,"maximum":100,"default":5}},"required":["kind"],"additionalProperties":false},{"type":"object","description":"Additional capacity for each fuel color while connected and functional.","properties":{"kind":{"const":"FuelCapacity"},"value":{"type":"integer","minimum":1,"maximum":100,"default":5}},"required":["kind"],"additionalProperties":false}]}}},"MissionArrivalResponseV9.schema.json":{"$schema":"https://json-schema.org/draft/2020-12/schema","$id":"https://scrap-pirates.example/schemas/MissionArrivalResponseV8.schema.json","title":"Scrap Pirates Story Snippets Response V8","description":"Draft AI-authoring contract. Defines additive story snippets that can begin with dialogue, progress through missions and encounters, and write localized world memories. The host owns eligibility, presentation, single-commit progression, journal lifecycle, and game mechanics. Story snippets are an unordered graph connected only by explicit prerequisites; array order never implies progress. Omit optional fields when unused. A conversation node is shown automatically when eligible and its speaker is available; no contact-action menu is required. V8 simplifies mission journaling to create/overwrite/append/complete, using one text field; title is required only when creating a mission journal entry. Journal resolution is described in prose and in the functional story outcome, not a separate result field.","type":"object","additionalProperties":false,"required":["locationRef","storySnippets","schemaVersion"],"properties":{"locationRef":{"type":"string","minLength":1,"description":"Location where these mission offers were generated. This is also the default location for mission contacts and scenes when they omit their own location."},"cargoDefinitions":{"type":"array","description":"Mission-specific cargo types used by these chains. Region responses do not define cargo.","items":{"$ref":"#/$defs/CargoDefinition"},"minItems":1},"contacts":{"type":"array","description":"Characters introduced by these missions. Once created, these contacts remain part of the world after mission completion.","items":{"$ref":"#/$defs/ContactDefinition"},"minItems":1},"storySnippets":{"type":"array","minItems":1,"description":"Unordered story graph for this response, containing dialogue, events, objectives, and encounters. Every snippet has a unique stable id in the persisted world. Include explicit prerequisites on non-entry nodes; omission creates an intentional eligible entry point. The host decides when to present eligible snippets, does not use array order, and commits outcomes at most once.","items":{"$ref":"#/$defs/StorySnippet"}},"entryContacts":{"type":"array","minItems":1,"uniqueItems":true,"items":{"type":"string","minLength":1},"description":"Stable IDs of contacts from the contacts definitions in this response that the host creates or reuses once when this story content is first installed. Use for story-entry speakers, not for contacts whose creation should follow a player choice. Contacts in definitions but not in entryContacts must be created by StoryFunction CreateContact or already exist in the persisted world. The host validates references and makes entry contacts present at their defined locations before first eligibility evaluation."},"schemaVersion":{"const":8}},"$defs":{"CargoDefinition":{"type":"object","additionalProperties":false,"required":["id","name"],"properties":{"id":{"type":"string","minLength":1,"description":"Stable ID used to reference this mission cargo type."},"name":{"type":"string","minLength":1,"description":"Player-facing name of the cargo item."},"questOnly":{"type":"boolean","description":"Whether ordinary selling or disposal is blocked. Omit for the usual mission-cargo value of true; set false only when this mission-created cargo should behave like ordinary tradable cargo.","default":true}}},"ContactDefinition":{"type":"object","additionalProperties":false,"required":["id","name","role","appearanceBrief"],"properties":{"id":{"type":"string","minLength":1,"description":"Stable world ID for the contact. Mission cleanup does not delete the resulting contact."},"name":{"type":"string","minLength":1,"description":"Player-facing name of the contact."},"factionRef":{"type":"string","minLength":1,"description":"Faction this contact belongs to. Omit when unaffiliated."},"locationRef":{"type":"string","minLength":1,"description":"Persistent home/base location. Omit to use the response locationRef."},"systemRef":{"type":"string","minLength":1,"description":"Star-system address associated with the contact when they are encountered in space."},"shipCardRef":{"type":"string","minLength":1,"description":"Ship-card definition used when this contact is encountered in space."},"role":{"type":"string","minLength":1,"description":"What this character does and what generally motivates their behavior."},"appearanceBrief":{"type":"string","minLength":1,"description":"Concise visual description used for portraits and consistent presentation."},"secretInfo":{"type":"string","description":"Hidden durable character context for narrative generation. Omit when there is nothing secret to preserve.","minLength":1},"shownFromStart":{"type":"boolean","description":"Is the contact at the given location immediately? Otherwise, it must be revealed from a mission outcome. "}},"description":"Contacts are characters the player can interact with in the world. They're touchstones for missions, and the player can talk to the DM through the lens of any contact, allowing more missions to be generated. They also remember past events with the log function in missions."},"CreateContactFunction":{"type":"object","additionalProperties":false,"required":["kind","contactRef"],"properties":{"kind":{"const":"CreateContact","description":"Creates or reuses a mission-defined persistent contact."},"contactRef":{"type":"string","minLength":1,"description":"ID of a contact defined in the story response. Creation reveals it to the player once they're in the proper location. "}}},"CreateShipFunction":{"type":"object","additionalProperties":false,"required":["kind","shipId","name","shipCardRef","factionRef","systemRef"],"properties":{"kind":{"const":"CreateShip","description":"Creates a persistent ship instance needed by the mission."},"shipId":{"type":"string","minLength":1,"description":"Stable ID for the created ship instance."},"name":{"type":"string","minLength":1,"description":"Player-facing ship name."},"shipCardRef":{"type":"string","minLength":1,"description":"Ship-card definition used to build the ship manifest."},"factionRef":{"type":"string","minLength":1,"description":"Faction that owns or operates the ship."},"systemRef":{"type":"string","minLength":1,"description":"Star-system address where the ship is initially placed."},"contactRef":{"type":"string","minLength":1,"description":"Optional mission contact associated with the ship. This allows dialog interaction to take place - if not present, the ship will just be a generic ally/enemy depending on the faction. "}}},"ChangeCreditsFunction":{"type":"object","additionalProperties":false,"required":["kind","delta"],"properties":{"kind":{"const":"ChangeCredits","description":"Changes the captain’s credits as a committed mission effect."},"delta":{"type":"integer","description":"Signed credit change. Positive values pay the captain; negative values charge them."}}},"StartEncounterFunction":{"type":"object","additionalProperties":false,"required":["kind","encounterKey","shipRefs"],"properties":{"kind":{"const":"StartEncounter","description":"Starts a combat encounter using already-created mission ships."},"encounterKey":{"type":"string","minLength":1,"description":"Globally unique stable encounter key in the persisted story graph; no Chain-local namespace exists."},"shipRefs":{"type":"array","minItems":1,"items":{"type":"string","minLength":1},"description":"Existing ship instance IDs taking part as hostile opponents; the engine validates all references."}}},"UpdateLocationFunction":{"type":"object","additionalProperties":false,"required":["kind","locationRef","prompt"],"properties":{"kind":{"const":"UpdateLocation","description":"Requests a validated DM update to an existing location after a story consequence."},"locationRef":{"type":"string","minLength":1,"description":"Stable location ID to update. "},"prompt":{"type":"string","minLength":1,"description":"Plain-language description of what changed and what existing facts should be preserved."}}},"UpdateContactFunction":{"type":"object","additionalProperties":false,"required":["kind","contactRef","prompt"],"properties":{"kind":{"const":"UpdateContact","description":"Requests a validated DM update to an existing persistent contact after a story consequence."},"contactRef":{"type":"string","minLength":1,"description":"Stable contact ID to update; the update must preserve the contact’s identity."},"prompt":{"type":"string","minLength":1,"description":"Plain-language description of what changed and what established character facts should remain intact."}}},"EncounterOutcomePrerequisite":{"type":"object","additionalProperties":false,"required":["encounterRef","outcome","kind"],"properties":{"encounterRef":{"type":"string","minLength":1,"description":"Globally unique key for a prior engine encounter result in this same mission response. Never infer from narrative."},"outcome":{"type":"string","minLength":1,"description":"Required encounter result, such as victory, escaped, or defeated.","enum":["victory","escaped","defeated"]},"kind":{"const":"encounterOutcome","description":""}},"description":"True only after the engine commits the named result of a specific encounter."},"AllPrerequisite":{"type":"object","additionalProperties":false,"required":["conditions","kind"],"properties":{"conditions":{"type":"array","minItems":1,"description":"Prerequisites that must all be true.","items":{"$ref":"#/$defs/StoryPrerequisite"}},"kind":{"const":"AND","description":""}},"description":"Logical AND for multiple prerequisites"},"AnyPrerequisite":{"type":"object","additionalProperties":false,"required":["conditions","kind"],"properties":{"conditions":{"type":"array","minItems":1,"description":"Alternative prerequisites; any one may unlock the scene.","items":{"$ref":"#/$defs/StoryPrerequisite"}},"kind":{"const":"OR","description":""}},"description":"Requires at least one nested prerequisite to be satisfied."},"LocalDialogueChoice":{"type":"object","additionalProperties":false,"required":["label","kind","narrative","id"],"properties":{"label":{"type":"string","minLength":1,"description":"Short player-facing button or response label."},"kind":{"const":"LocalDialogue","description":"Shows stored dialogue without completing the scene."},"narrative":{"type":"string","description":"Stored dialogue shown immediately without a new text request. Should be flavor only, as the player will still be faced with the same other dialog choices - make a new snippet if an entirely new set of choices is needed.","minLength":1},"id":{"type":"string","minLength":1}},"description":"Reveals authored dialogue within the current snippet without committing an outcome or changing snippet eligibility."},"RecruitCrewFunction":{"type":"object","additionalProperties":false,"required":["kind","contactRef"],"properties":{"kind":{"const":"RecruitCrew"},"contactRef":{"type":"string","minLength":1}},"description":"Allows the player to take a contact along with them until further notice, or until dismissed by the player. This is mainly thematic, but does increase player and story interaction with the contact in question."},"RecruitAllyFunction":{"type":"object","additionalProperties":false,"required":["kind","shipRef"],"properties":{"kind":{"const":"RecruitAlly"},"shipRef":{"type":"string","minLength":1}},"description":"Recruit an ally ship that will assist in battle. "},"ChangeCargoFunction":{"type":"object","additionalProperties":false,"required":["kind","cargoRef","delta"],"properties":{"kind":{"const":"ChangeCargo","description":"Changes the captain’s mission cargo after normal capacity/ownership validation."},"cargoRef":{"type":"string","minLength":1,"description":"Mission cargo definition to change."},"delta":{"type":"integer","not":{"const":0},"description":"Signed item-count change. Positive values add cargo; negative values remove it."}}},"AddLogFunction":{"type":"object","additionalProperties":false,"required":["kind","targetType","targetRef","statement","importance"],"properties":{"kind":{"const":"AddLog","description":"Adds a durable narrative memory to a faction, location, or contact when a story outcome commits. This should be used when the player is involved in important events for a faction, location, or contact."},"targetType":{"type":"string","enum":["Faction","Location","Contact"],"description":"Type of world entity that receives the log."},"targetRef":{"type":"string","minLength":1,"description":"Stable ID of the faction, location, or contact that receives the log."},"statement":{"type":"string","minLength":1,"description":"Concise narrative fact this entity should remember from the mission event. Write durable context, not transient dialogue."},"importance":{"type":"integer","minimum":1,"maximum":1000,"description":"Relative retention priority among this entity’s logs; higher-importance memories are kept longer. Calibrate roughly: 1–10 is a notable event that makes the entity remember the player; 10–100 elicits an emotional response or affects the entity personally/materially; 100–1000 is a foundational change such as an existential threat or worldview revelation. Boundary ranges intentionally overlap; choose importance relative to the entity’s other memories."}}},"StoryFunction":{"description":"Validated engine effect to commit atomically and exactly once with the selected StorySnippet outcome. Do not use to start or progress a mission journal; use the StorySnippet.mission.onOutcome journal event. Effect arrays are applied in listed order after preflight validation. StartEncounter should be last.","oneOf":[{"$ref":"#/$defs/CreateContactFunction"},{"$ref":"#/$defs/CreateShipFunction"},{"$ref":"#/$defs/ChangeCargoFunction"},{"$ref":"#/$defs/ChangeCreditsFunction"},{"$ref":"#/$defs/StartEncounterFunction"},{"$ref":"#/$defs/UpdateLocationFunction"},{"$ref":"#/$defs/UpdateContactFunction"},{"$ref":"#/$defs/RecruitCrewFunction"},{"$ref":"#/$defs/RecruitAllyFunction"},{"$ref":"#/$defs/AddLogFunction"},{"$ref":"#/$defs/RevealLocationFunction"},{"$ref":"#/$defs/GrantGatePasswordFunction"}]},"RevealLocationFunction":{"type":"object","additionalProperties":false,"required":["kind","locationRef"],"description":"Reveals a landable/dockable location that was previously hidden, whether due to lack of access or awareness on behalf of the player. ","properties":{"kind":{"const":"RevealLocation"},"locationRef":{"type":"string","minLength":1,"description":"Existing location to expose on the captain navigation/map."}}},"StoryOutcomePrerequisite":{"type":"object","additionalProperties":false,"required":["kind","snippetRef","outcome"],"description":"True only after the referenced StorySnippet committed exactly the named outcome. Generally \"completed\" but for branching storylines, custom outcome names are necessary.","properties":{"kind":{"const":"StoryOutcome"},"snippetRef":{"type":"string","minLength":1,"description":"Stable ID of another story snippet, never an array index."},"outcome":{"type":"string","minLength":1,"description":"Declared outcome token of the referenced snippet."}}},"StoryPrerequisite":{"description":"Explicit eligibility rule for this snippet. Omitting this field declares an intentional story entry point: it is eligible subject to current place, speaker presence, and host arbitration. Never omit this merely because an earlier snippet appears before it in the JSON array. The host evaluates only committed outcomes, not prose or logs.","oneOf":[{"$ref":"#/$defs/StoryOutcomePrerequisite"},{"$ref":"#/$defs/EncounterOutcomePrerequisite"},{"$ref":"#/$defs/AllPrerequisite"},{"$ref":"#/$defs/AnyPrerequisite"}]},"CompleteSnippetChoice":{"type":"object","additionalProperties":false,"required":["kind","label","outcome","id"],"properties":{"kind":{"const":"CompleteSnippet"},"label":{"type":"string","minLength":1,"description":"Concise, meaningful player-facing option - a choice in a decision/dialog tree. Different choices should imply a real narrative difference."},"narrative":{"type":"string","minLength":1,"description":"Optional authored line shown after selection and before the next snippet; omit when unnecessary."},"outcome":{"type":"string","minLength":1,"description":"One of the owning snippet outcomes. The host commits the outcome, matching outcomeEffects and journal event exactly once."},"id":{"type":"string","minLength":1}}},"StoredChoice":{"description":"Player-facing response. Authored choices are helpful guidance, not a prohibition on freeform actions. The host never invents mechanical effects for a local dialogue line.","oneOf":[{"$ref":"#/$defs/CompleteSnippetChoice"},{"$ref":"#/$defs/LocalDialogueChoice"}]},"MissionJournalEvent":{"type":"object","additionalProperties":false,"description":"A single player-facing mission journal mutation committed only after the enclosing story snippet commits the keyed outcome. Journal updates are presentation, not progress predicates; they never trigger on eligibility or display. Use AddLog for durable contact/faction/location history instead.","required":["operation","text"],"properties":{"operation":{"type":"string","enum":["create","overwrite","append","complete"],"description":"create: make a new active journal entry with title and text; overwrite: replace the full journal body, retaining its original title and active state; append: add text as a separate paragraph; complete: append the closing text and mark the journal entry inactive."},"title":{"type":"string","minLength":1,"description":"Player-facing mission title; required for create and optional for overwrite. The host retains the title on subsequent mutations."},"text":{"type":"string","minLength":1,"description":"Player-facing journal body. On create, initial mission description/objective; on overwrite, complete replacement body; on append, a new paragraph, sentence, or phrase; on complete, closing paragraph explaining the resolution."}}},"MissionJournalBinding":{"type":"object","additionalProperties":false,"required":["missionRef","onOutcome"],"description":"Optional tracked player-mission journal mutations, independent of StorySnippet.kind and distinct from entity AddLog history. Mutations run once on the keyed committed outcome; create must precede append/overwrite/complete for the same missionRef. A completed journal is inactive. The engine uses story outcomes to decide progression and narrative text to describe resolution.","properties":{"missionRef":{"type":"string","minLength":1,"description":"Stable player mission journal ID, shared by all snippets contributing to that mission. create makes a new entry under this ID; other operations mutate the existing active entry."},"onOutcome":{"type":"object","minProperties":1,"propertyNames":{"minLength":1},"additionalProperties":{"$ref":"#/$defs/MissionJournalEvent"},"description":"Map of this snippet’s declared outcome tokens to one journal mutation each. Keys must be a subset of StorySnippet.outcomes (checked by the host). Omit entries when the outcome has no meaningful player-facing journal change."}}},"StorySnippet":{"type":"object","additionalProperties":false,"required":["id","kind","narrative","outcomes"],"description":"One independently addressable narrative beat in an unordered world story graph.  Mission journal participation is controlled solely by the optional mission field. Showing a snippet does not commit an outcome, start a mission, or execute effects. An active conversation automatically advances to the next eligible ConversationNode at this location, without an extra Talk action.","properties":{"id":{"type":"string","minLength":1,"description":"Globally unique stable ID in the persisted world story graph. References resolve by ID, never array order."},"kind":{"type":"string","enum":["ConversationNode","MissionNode"],"description":"ConversationNode is a lighter narrative episode that allows interaction without creating the full mission framework. Can be used to talk to someone that may or may not offer a mission, or just add flavor. \nMissionNode is an event, encounter, or objective, and may optionally have a speaker. The main distinction is it creates a mission log and objective flag for the player to follow.\nFunctionalNode is an event that occurs when the player reaches a location. Much like ConversationNode, but more focused on outcomeEffects."},"location":{"type":"string","minLength":1,"description":"Existing V6 place reference: either dockable location ID or star-system address. Omit to use this response's locationRef. Do not invent locations unless they are being added to the location list in this same response. "},"prerequisite":{"$ref":"#/$defs/StoryPrerequisite","description":"Explicit committed-outcome dependency; omit only for intentional story entry points, or standalone events."},"speakerRef":{"type":"string","minLength":1,"description":"Contact who speaks in this node. If present in the data, the contact must also be present at the location with the player in order for this snippet to activate."},"narrative":{"type":"string","minLength":1,"description":"Player-facing opening of this beat. Set the scene, introduce any new characters, and describe what happens on the ground, or what is said. Gameplay happens in space, and anything ship-combat based or travel-based should be left for the client to resolve. "},"secrets":{"type":"string","minLength":1,"description":"Hidden information for the DM to interpret unexpected player responses. Never revealed automatically."},"outcomes":{"type":"array","minItems":1,"uniqueItems":true,"items":{"type":"string","minLength":1},"description":"Allowed tokens this node may commit for prerequisites of subsequent snippets, and for initiating game engine based outcomeEffects.Only committed outcomes affect progression. Maybe \"accepted\" or \"refused\" if the player is making a choice, or just \"completed.\"  These strings have no inherit engine effects; they are the glue that connects this snippet to other snippets and outcomeEffects."},"storedChoices":{"type":"array","minItems":1,"items":{"$ref":"#/$defs/StoredChoice"},"description":"Optional guided choices - buttons the player can use to select what to say or do with pre-generated dialog and outcomes. The player may also reply in freeform; freeform DM can choose an outcome declared here or generate new story graph."},"outcomeEffects":{"type":"object","minProperties":1,"propertyNames":{"minLength":1},"additionalProperties":{"type":"array","minItems":1,"items":{"$ref":"#/$defs/StoryFunction"}},"description":"Maps an outcome token to validated engine effects. Keys MUST be declared in outcomes; the host checks. Effects belong to outcomes, not individual buttons, so typed freeform replies and stored choices that commit the same outcome have identical mechanical consequences. "},"mission":{"$ref":"#/$defs/MissionJournalBinding","description":"Update the player's personal mission log. "},"offerChance":{"type":"number","description":"Probability (0-1) of this StorySnippet showing up when all prerequisites are fulfilled and the player visits the required location/contact. Use this for periodic random events or story entry points that may require the player to hang around an area for a while, never in the middle of a narrative chain. Default 1."},"repeatable":{"type":"boolean","description":"If true, this isn't a storyline but an event that can happen multiple times. Think \"attack on this system and the player has to help defend it\" or something."}}},"GrantGatePasswordFunction":{"type":"object","additionalProperties":false,"required":["kind","systemRef"],"properties":{"kind":{"const":"GrantGatePassword"},"systemRef":{"type":"string","pattern":"^[1-7]{1,13}$","description":"Hacked/rooted gates are a form of fast travel - the player can travel to this location's parent gate from any other hacked gate once they have this \"password.\" Occasionally use this when the player gains the trust of a local roguish faction. "}}}}}};
